/**
 * @suppress
 */
public object FfiConverterTypeLampcordClient: FfiConverter<LampcordClient, Pointer> {

    override fun lower(value: LampcordClient): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): LampcordClient {
        return LampcordClient(value)
    }

    override fun read(buf: ByteBuffer): LampcordClient {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: LampcordClient) = 8UL

    override fun write(value: LampcordClient, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



