/**
 * @suppress
 */
public object FfiConverterTypeClientCommand : FfiConverterRustBuffer<ClientCommand>{
    override fun read(buf: ByteBuffer): ClientCommand {
        return when(buf.getInt()) {
            1 -> ClientCommand.ConnectToken(
                FfiConverterString.read(buf),
                )
            2 -> ClientCommand.SelectGuild(
                FfiConverterOptionalULong.read(buf),
                )
            3 -> ClientCommand.SelectChannel(
                FfiConverterOptionalULong.read(buf),
                )
            4 -> ClientCommand.FetchMessages(
                FfiConverterULong.read(buf),
                FfiConverterOptionalULong.read(buf),
                FfiConverterOptionalUByte.read(buf),
                )
            5 -> ClientCommand.SendMessage(
                FfiConverterULong.read(buf),
                FfiConverterString.read(buf),
                FfiConverterOptionalULong.read(buf),
                FfiConverterOptionalULong.read(buf),
                )
            6 -> ClientCommand.Logout
            7 -> ClientCommand.Shutdown
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ClientCommand) = when(value) {
        is ClientCommand.ConnectToken -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`token`)
            )
        }
        is ClientCommand.SelectGuild -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterOptionalULong.allocationSize(value.`guildId`)
            )
        }
        is ClientCommand.SelectChannel -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterOptionalULong.allocationSize(value.`channelId`)
            )
        }
        is ClientCommand.FetchMessages -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`channelId`)
                + FfiConverterOptionalULong.allocationSize(value.`before`)
                + FfiConverterOptionalUByte.allocationSize(value.`limit`)
            )
        }
        is ClientCommand.SendMessage -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`channelId`)
                + FfiConverterString.allocationSize(value.`content`)
                + FfiConverterOptionalULong.allocationSize(value.`replyToMessageId`)
                + FfiConverterOptionalULong.allocationSize(value.`replyToGuildId`)
            )
        }
        is ClientCommand.Logout -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is ClientCommand.Shutdown -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: ClientCommand, buf: ByteBuffer) {
        when(value) {
            is ClientCommand.ConnectToken -> {
                buf.putInt(1)
                FfiConverterString.write(value.`token`, buf)
                Unit
            }
            is ClientCommand.SelectGuild -> {
                buf.putInt(2)
                FfiConverterOptionalULong.write(value.`guildId`, buf)
                Unit
            }
            is ClientCommand.SelectChannel -> {
                buf.putInt(3)
                FfiConverterOptionalULong.write(value.`channelId`, buf)
                Unit
            }
            is ClientCommand.FetchMessages -> {
                buf.putInt(4)
                FfiConverterULong.write(value.`channelId`, buf)
                FfiConverterOptionalULong.write(value.`before`, buf)
                FfiConverterOptionalUByte.write(value.`limit`, buf)
                Unit
            }
            is ClientCommand.SendMessage -> {
                buf.putInt(5)
                FfiConverterULong.write(value.`channelId`, buf)
                FfiConverterString.write(value.`content`, buf)
                FfiConverterOptionalULong.write(value.`replyToMessageId`, buf)
                FfiConverterOptionalULong.write(value.`replyToGuildId`, buf)
                Unit
            }
            is ClientCommand.Logout -> {
                buf.putInt(6)
                Unit
            }
            is ClientCommand.Shutdown -> {
                buf.putInt(7)
